import{S as s,o as d,c as a,a9 as i,B as n}from"./chunks/framework.IJ8axLs_.js";const p="/agentsrc/images/deepseek/01-plugin-tree.svg",k=JSON.parse('{"title":"DeepSeek Harness 全景：一切皆插件的通用 agent 引擎","description":"","frontmatter":{"title":"DeepSeek Harness 全景：一切皆插件的通用 agent 引擎"},"headers":[],"relativePath":"deepseek/01-overview.md","filePath":"deepseek/01-overview.md","lastUpdated":1790217011000}'),c={name:"deepseek/01-overview.md"},g=Object.assign(c,{setup(l){const t=[{question:"下列哪一项最符合 `dsh` 的架构定位？",options:["一切皆插件，循环本身也只是默认实现","中央主循环固定，其余模块围绕它注册","循环写死在核心，扩展必须改代码","与 OpenCode 相同，runLoop 位于中心"],correct:0,explanation:'dsh 的 everything is a plugin 加无特权核心：agent-loop 只是默认实现且 swappable。B/C 是前三栏"循环写死"的模式，D 把 OpenCode 的结构与 dsh 混为一谈。'},{question:"profile 装配的层叠顺序，正确的是？",options:["home patch → bundle 层序 → profile patch → 覆盖","按包名字典序应用，与声明顺序无关","bundle 层序 → profile patch → home patch → --patch","--patch → profile patch → bundle 层序 → home patch"],correct:2,explanation:"每个 profile 从空配置起步，先按列出顺序叠 bundle，再叠 profile 自己的 cordis.patch.yml，然后是 home 级文件，命令行 --patch 权限最高。A 把 home 级提前了，D 整个倒置，B 的字典序不存在——层序由 profile 声明决定。"},{question:"`dsh --profile web --dump-config` 的用途是？",options:["打印这台机器实际会启动的配置树","导出 Web 前端的构建产物","新建一个叫 dump-config 的 profile","从当前 profile 卸载指定插件"],correct:0,explanation:"dump-config 不启动、不请求模型，只打印叠好的整棵插件树，且每一行都能被自己的 patch 替换。B 把配置树当成了构建产物，C 混淆了它和 profile 创建命令，D 把审查能力当成了管理操作。"},{question:"`sdk-minimal` 这个 bundle 的特殊之处在于？",options:["它是 base 的精简版，只装半个 base","它不用 dsh-base，单一 bundle 独占完整显式树","它只能被 Python SDK 使用，其他入口禁止","它把 agent-loop 替换成了专用循环"],correct:1,explanation:'架构文档称它为 deliberate exception：不套 dsh-base，由一个 bundle 持有完整的显式 SDK 树，用来证明从零组一棵干净的树是可行的。A 的"精简 base"说反了它的独立路线，C 没有这个入口限制，D 与循环无关。'},{question:'"Extension plugins depend on Service Definitions, never concrete providers" 这条规则直接保证了什么？',options:["扩展插件的加载顺序由依赖图自动推导","所有插件必须发布到 npm 公共仓库","Service Provider 之间禁止互相调用","换 Provider 实现时扩展插件不用改代码"],correct:3,explanation:"插件只依赖接口包（如 dsh-agent），不 import 具体 provider（如 dsh-agent-loop），所以替换实现时消费方不动。A 说的是 inject 依赖声明的另一件事，B/C 都不是这条规则的内容。"}];return(r,e)=>{const o=s("Quiz");return d(),a("div",null,[e[0]||(e[0]=i("",45)),n(o,{questions:t})])}}});export{k as __pageData,g as default};
